class SessionStore(private val c:Context){
 private val alias="localdukaan_session_key";private val prefs=c.getSharedPreferences("secure_session",Context.MODE_PRIVATE)
 private fun key():javax.crypto.SecretKey{val ks=java.security.KeyStore.getInstance("AndroidKeyStore").apply{load(null)};return (ks.getKey(alias,null) as? javax.crypto.SecretKey)?:javax.crypto.KeyGenerator.getInstance(android.security.keystore.KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore").run{init(android.security.keystore.KeyGenParameterSpec.Builder(alias,android.security.keystore.KeyProperties.PURPOSE_ENCRYPT or android.security.keystore.KeyProperties.PURPOSE_DECRYPT).setBlockModes(android.security.keystore.KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(android.security.keystore.KeyProperties.ENCRYPTION_PADDING_NONE).build());generateKey()}}
 private fun encrypt(v:String):String{val cipher=javax.crypto.Cipher.getInstance("AES/GCM/NoPadding");cipher.init(javax.crypto.Cipher.ENCRYPT_MODE,key());return android.util.Base64.encodeToString(cipher.iv+cipher.doFinal(v.toByteArray()),android.util.Base64.NO_WRAP)}
 private fun decrypt(v:String?):String?=runCatching{if(v==null)return null;val b=android.util.Base64.decode(v,android.util.Base64.NO_WRAP);val cipher=javax.crypto.Cipher.getInstance("AES/GCM/NoPadding");cipher.init(javax.crypto.Cipher.DECRYPT_MODE,key(),javax.crypto.spec.GCMParameterSpec(128,b.copyOfRange(0,12)));String(cipher.doFinal(b.copyOfRange(12,b.size)))}.getOrNull()
 fun access()=decrypt(prefs.getString("access",null));fun refresh()=decrypt(prefs.getString("refresh",null));fun save(a:String,r:String)=prefs.edit().putString("access",encrypt(a)).putString("refresh",encrypt(r)).apply();fun clear()=prefs.edit().clear().apply();fun loggedIn()=access()!=null
}
class AppRepository(private val context:Context,private val db:LocalDatabase,private val sessions:SessionStore){private val api=ApiClient{sessions.access()};val profile:Flow<LocalProfile?> = db.dao().profile();val shops:Flow<List<LocalShop>> = db.dao().shops()
 suspend fun register(phone:String,pin:String,confirm:String,role:String){val x=api.call("/v1/auth/register","POST",JSONObject().put("phone",phone).put("pin",pin).put("confirmPin",confirm).put("role",role).put("deviceName","Android"));sessions.save(x.getString("accessToken"),x.getString("refreshToken"));refreshProfile()}
 suspend fun login(phone:String,pin:String){val x=api.call("/v1/auth/login","POST",JSONObject().put("phone",phone).put("pin",pin).put("deviceName","Android"));sessions.save(x.getString("accessToken"),x.getString("refreshToken"));refreshProfile()}
 suspend fun saveProfile(name:String,hi:Boolean,customer:Boolean,shopkeeper:Boolean){val x=api.call("/v1/profile","PUT",JSONObject().put("displayName",name).put("preferredLanguage",if(hi)"hi" else "en").put("isCustomer",customer).put("isShopkeeper",shopkeeper),true);db.dao().putProfile(LocalProfile(x.getString("user_id"),x.getString("display_name"),x.getString("preferred_language"),x.getInt("is_customer")==1,x.getInt("is_shopkeeper")==1,true))}
 suspend fun refreshProfile(){val x=api.call("/v1/profile",authenticated=true);db.dao().putProfile(LocalProfile(x.getString("user_id"),x.optString("display_name"),x.optString("preferred_language","en"),x.optInt("is_customer")==1,x.optInt("is_shopkeeper")==1,true))}
 suspend fun profileNow()=db.dao().profile().first()
 /** Startup resolver ke liye fresh DB truth — StateFlow emission ka wait nahi karna padta. */
 suspend fun shopsNow()=db.dao().shops().first()
 suspend fun restoreSession(){runCatching{refreshProfile()}.getOrElse{val refresh=sessions.refresh()?:throw it;val x=api.call("/v1/auth/refresh","POST",JSONObject().put("refreshToken",refresh));sessions.save(x.getString("accessToken"),x.getString("refreshToken"));refreshProfile()}}
 suspend fun createShop(name:String,owner:String,address:String,locality:String,city:String,pincode:String,category:String,lat:Double,lng:Double){val mutation=UUID.randomUUID().toString();val b=JSONObject().put("mutationId",mutation).put("name",name).put("ownerName",owner).put("addressLine",address).put("locality",locality).put("city",city).put("pincode",pincode).put("category",category).put("latitude",lat).put("longitude",lng);val x=api.call("/v1/shops","POST",b,true);db.dao().putShop(LocalShop(x.getString("id"),name,city,locality,x.getString("status"),true,ownerName=owner,addressLine=address,pincode=pincode,isPublished=true,version=1))}
 // Poori shop row yaad rakhte hain (address, pincode, LIVE status, version) — pehle sirf naam/city
 // aata tha, jisse dashboard ka LIVE/NOT-LIVE chip galat dikhta tha aur publish 400 deta tha.
 // REPLACE-list sync: jo shops server par ab is user ke NAHI hain, unka local data WIPE ho jaata hai.
 // (Yahi root cause tha ki logout ke baad dusra login purane account ke shops dekh leta tha.)
 suspend fun loadShops(){val x=api.call("/v1/shops/mine",authenticated=true).getJSONArray("items");val ids=mutableListOf<String>();for(i in 0 until x.length()){val s=x.getJSONObject(i);val sid=s.getString("id");ids.add(sid);db.dao().putShop(LocalShop(sid,s.getString("name"),s.getString("city"),s.getString("locality"),s.getString("status"),true,ownerName=text(s,"owner_name")?:"",phone=text(s,"phone_e164"),addressLine=text(s,"address_line")?:"",pincode=text(s,"pincode")?:"",description=text(s,"description"),publicSlug=text(s,"public_slug"),isPublished=s.optInt("is_published")==1,version=s.optLong("version",1)))};if(ids.isNotEmpty()){val dao=db.dao();db.withTransaction{dao.deleteSaleItemsNotInShops(ids);dao.deleteSalesNotInShops(ids);dao.deleteInventoryNotInShops(ids);dao.deleteCreditNotInShops(ids);dao.deletePurchaseNotInShops(ids);dao.deleteShopCustomersNotInShops(ids);dao.deleteOrphanCustomers();dao.deleteShopProductsNotInShops(ids);dao.deleteShopsNotIn(ids)}}}
 suspend fun downloadProductImage(shopId:String,shopProductId:String)=api.download("/v1/shops/$shopId/products/$shopProductId/image")
 suspend fun downloadUrl(url:String):ByteArray=kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO){val c=(java.net.URL(url).openConnection() as java.net.HttpURLConnection).apply{connectTimeout=15000;readTimeout=20000;setRequestProperty("user-agent","LocalDukaan/1.0")}
  try{if(c.responseCode !in 200..299)throw java.io.IOException("Image download failed");c.inputStream.use{it.readBytes()}}finally{runCatching{c.disconnect()}}}
 fun observeProducts(shopId:String):Flow<List<ProductRow>> = db.dao().products(shopId)
 suspend fun refreshProducts(shopId:String){val items=api.call("/v1/shops/$shopId/products",authenticated=true).getJSONArray("items");db.withTransaction{for(i in 0 until items.length())mergeProduct(items.getJSONObject(i),"SYNCED")}}
 fun dashboard(shopId:String):Flow<Triple<List<DailySaleRow>,List<DailyProfitRow>,StockValueRow?>> = kotlinx.coroutines.flow.combine(db.dao().dailySales(shopId),db.dao().dailyProfit(shopId),db.dao().stockValue(shopId)){a,b,c->Triple(a,b,c)}
 suspend fun dues(shopId:String):Pair<Long,Int> = db.dao().totalDue(shopId) to db.dao().dueCount(shopId)
 suspend fun publishShop(shop:LocalShop,publish:Boolean){val mutation=UUID.randomUUID().toString();val b=JSONObject().put("mutationId",mutation).put("version",shop.version).put("name",shop.name.ifBlank{"My Shop"}).put("ownerName",shop.ownerName.ifBlank{"Owner"}).put("addressLine",shop.addressLine.ifBlank{"Address"}).put("locality",shop.locality.ifBlank{"Locality"}).put("city",shop.city.ifBlank{"City"}).put("pincode",shop.pincode.ifBlank{"000000"}).put("phone",shop.phone?:JSONObject.NULL).put("description",shop.description?:JSONObject.NULL).put("isPublished",publish);val x=api.call("/v1/shops/${shop.id}/profile","PUT",b,true);db.dao().putShop(shop.copy(isPublished=x.getBoolean("isPublished"),version=x.getLong("version"),publicSlug=x.optString("publicSlug"),synced=true))}
 suspend fun addProduct(shopId:String,d:ProductDraft,image:SelectedImage?=null,globalProductId:String?=null){val validation=ProductRules.validate(d);require(validation.valid){validation.message!!};val mutation=UUID.randomUUID().toString();val globalId="local-global-$mutation";val localId="local-$mutation";val price=ProductRules.priceToPaise(d.priceText)!!;val cost=ProductRules.priceToPaise(d.costPriceText)?:0L;val opening=ProductRules.quantityToMilli(d.openingStockText)!!;val minimum=ProductRules.quantityToMilli(d.minimumStockText)!!;val now=System.currentTimeMillis();val payload=JSONObject().put("mutationId",mutation).put("shopId",shopId).put("name",d.name.trim()).put("brand",d.brand.trim().takeIf{it.isNotBlank()} ?: JSONObject.NULL).put("barcode",ProductRules.normalizeBarcode(d.barcode)?:JSONObject.NULL).put("unit",d.unit.trim()).put("description",d.description.trim().takeIf{it.isNotBlank()} ?: JSONObject.NULL).put("sellingPricePaise",price).put("openingStockMilli",opening).put("minimumStockMilli",minimum).put("isAvailable",d.available).put("productId",globalProductId?:JSONObject.NULL).toString();db.withTransaction{db.dao().putProduct(ProductEntity(globalId,ProductRules.normalizeBarcode(d.barcode),d.name.trim(),d.brand.trim().takeIf{it.isNotBlank()},d.unit.trim(),d.description.trim().takeIf{it.isNotBlank()},now));db.dao().putShopProduct(ShopProductEntity(localId,shopId,globalId,price,opening,0,minimum,d.available,false,null,1,"PENDING",now,costPricePaise=cost));if(opening>0)db.dao().putInventory(InventoryTransactionEntity("local-tx-$mutation",shopId,localId,"OPENING_STOCK",opening,opening,mutation,now));db.dao().enqueue(Outbox(mutation,"CREATE_PRODUCT",payload));if(image!=null)queueImageLocked(shopId,localId,image)};scheduleSync()}
 suspend fun updateProduct(shopId:String,row:ProductRow,d:ProductDraft,image:SelectedImage?=null){val validation=ProductRules.validate(d);require(validation.valid){validation.message!!};val mutation=UUID.randomUUID().toString();val cost=ProductRules.priceToPaise(d.costPriceText)?:row.shopProduct.costPricePaise;val payload=JSONObject().put("mutationId",mutation).put("version",row.shopProduct.version).put("name",d.name.trim()).put("brand",d.brand.takeIf{it.isNotBlank()} ?: JSONObject.NULL).put("barcode",ProductRules.normalizeBarcode(d.barcode)?:JSONObject.NULL).put("unit",d.unit.trim()).put("description",d.description.takeIf{it.isNotBlank()} ?: JSONObject.NULL).put("sellingPricePaise",ProductRules.priceToPaise(d.priceText)).put("minimumStockMilli",ProductRules.quantityToMilli(d.minimumStockText)).put("isAvailable",d.available).put("shopId",shopId).put("shopProductId",row.shopProduct.id).toString();db.withTransaction{db.dao().putProduct(row.product.copy(name=d.name.trim(),brand=d.brand.takeIf{it.isNotBlank()},barcode=ProductRules.normalizeBarcode(d.barcode),unit=d.unit,description=d.description.takeIf{it.isNotBlank()},updatedAt=System.currentTimeMillis()));db.dao().putShopProduct(row.shopProduct.copy(sellingPricePaise=ProductRules.priceToPaise(d.priceText)!!,minimumStockMilli=ProductRules.quantityToMilli(d.minimumStockText)!!,isAvailable=d.available,syncState="PENDING",costPricePaise=cost));db.dao().enqueue(Outbox(mutation,"UPDATE_PRODUCT",payload));if(image!=null)queueImageLocked(shopId,row.shopProduct.id,image)};scheduleSync()}
 suspend fun archiveProduct(shopId:String,id:String){val mutation=UUID.randomUUID().toString();val payload=JSONObject().put("mutationId",mutation).put("shopId",shopId).put("shopProductId",id).toString();db.withTransaction{db.dao().archiveProduct(id);db.dao().enqueue(Outbox(mutation,"ARCHIVE_PRODUCT",payload))};scheduleSync()}
 private suspend fun queueImageLocked(shopId:String,shopProductId:String,image:SelectedImage){require(image.bytes.size in 1..5*1024*1024);require(image.mimeType in setOf("image/jpeg","image/png","image/webp"));val mutation=UUID.randomUUID().toString();val dir=java.io.File(context.filesDir,"pending-images").apply{mkdirs()};val file=java.io.File(dir,mutation);file.writeBytes(image.bytes);val payload=JSONObject().put("mutationId",mutation).put("shopId",shopId).put("shopProductId",shopProductId).put("filePath",file.absolutePath).put("mimeType",image.mimeType).toString();db.dao().setProductImage(shopProductId,"local-file:${file.absolutePath}","PENDING");db.dao().enqueue(Outbox(mutation,"UPLOAD_PRODUCT_IMAGE",payload))}
 suspend fun removeProductImage(shopId:String,row:ProductRow){val mutation=UUID.randomUUID().toString();val payload=JSONObject().put("mutationId",mutation).put("shopId",shopId).put("shopProductId",row.shopProduct.id).put("expectedImageKey",row.shopProduct.imageKey?:JSONObject.NULL).toString();db.withTransaction{db.dao().setProductImage(row.shopProduct.id,null,"PENDING");db.dao().enqueue(Outbox(mutation,"REMOVE_PRODUCT_IMAGE",payload))};scheduleSync()}
 private fun text(o:JSONObject,key:String)=o.optString(key).takeIf{it.isNotBlank()&&it!="null"}
 private fun globalImageUrl(code:String)="${BuildConfig.API_BASE_URL.trimEnd('/')}/v1/global-products/$code/image"
 suspend fun productByBarcode(shopId:String,raw:String):ProductRow?{for(code in BarcodeRules.candidates(raw))db.dao().productByBarcode(shopId,code)?.let{return it};return null}
 /** Scans reach us as whichever form the printer used, so every equivalent number is tried:
  *  the shop's own catalogue first, then the on-device copy of the global catalogue, then the
  *  server (Open Food / Beauty / Products Facts + UPCitemdb). Resolved globals are remembered
  *  locally so a second scan — even offline — is instant. */
 suspend fun resolveBarcode(shopId:String,raw:String):BarcodeResolution{
  val codes=BarcodeRules.candidates(raw)
  if(codes.isEmpty())return BarcodeResolution.Invalid("Invalid barcode")
  for(code in codes)db.dao().productByBarcode(shopId,code)?.let{return BarcodeResolution.Local(it)}
  db.dao().catalogueByBarcode(codes)?.let{return BarcodeResolution.Global(it.id,it.name,it.brand,it.unit,it.barcode?:codes.first(),null,globalImageUrl(it.barcode?:codes.first()))}
  val payload=JSONObject().put("barcode",codes.first()).put("candidates",org.json.JSONArray().apply{codes.forEach{put(it)}})
  return try{
   val x=api.call("/v1/products/barcode/lookup","POST",payload,true)
   if(!x.getBoolean("found"))BarcodeResolution.NotFound(codes.first())
   else x.getJSONObject("product").let{p->
    val barcode=text(p,"barcode")?:codes.first()
    runCatching{db.dao().putProduct(ProductEntity(p.getString("id"),barcode,p.getString("name"),text(p,"brand"),p.getString("unit"),text(p,"description"),System.currentTimeMillis()))}
    BarcodeResolution.Global(p.getString("id"),p.getString("name"),text(p,"brand"),p.getString("unit"),barcode,text(x,"imageBase64"),text(x,"imageUrl")?:globalImageUrl(barcode))
   }
  }catch(_:java.io.IOException){BarcodeResolution.Invalid("Internet nahi chal raha — product ka naam haath se daalo")}
 }
 suspend fun adjustStock(shopId:String,row:ProductRow,quantityMilli:Long,type:String,note:String){require(quantityMilli>0);val mutation=UUID.randomUUID().toString();val delta=if(type=="PURCHASE")quantityMilli else -quantityMilli;db.withTransaction{require(db.dao().adjustLocalStock(row.shopProduct.id,delta)==1){"Insufficient local stock"};db.dao().putInventory(InventoryTransactionEntity("local-$mutation",shopId,row.shopProduct.id,type,delta,row.shopProduct.stockQuantityMilli+delta,mutation,System.currentTimeMillis()));db.dao().enqueue(Outbox(mutation,if(type=="PURCHASE")"STOCK_IN" else "STOCK_OUT",JSONObject().put("mutationId",mutation).put("shopId",shopId).put("shopProductId",row.shopProduct.id).put("quantityMilli",quantityMilli).put("type",type).put("note",note).toString()))};scheduleSync()}
 /** POS sale: pehle LOCAL record + stock decrement (offline-first), phir outbox se server sync.
  *  Server reject hone par stock rollback hota hai aur sale REJECTED dikhata hai (RFC - sale draft retained).
  *  Idempotent: sale + inventory entries mutationId par keyed hain, retry duplicate nahi banata. */
 suspend fun completeQuickSale(shopId:String,sale:QuickSaleState):String{require(sale.lines.isNotEmpty());require(!sale.udhaariRequiresCustomer){"Customer details are required for Udhaari"};val mutation=UUID.randomUUID().toString();val localSale="local-sale-$mutation";val created=System.currentTimeMillis();val credit=sale.paymentMode==SalePaymentMode.CREDIT;val total=sale.totalPaise;val payload=JSONObject().put("mutationId",mutation).put("shopId",shopId).put("clientCreatedAt",created).put("paymentType",if(credit)"CREDIT" else "PAID").put("paymentMethod",sale.method.name).put("discountPaise",sale.discountPaise).put("items",org.json.JSONArray().apply{sale.lines.values.forEach{put(JSONObject().put("shopProductId",it.shopProductId).put("quantityMilli",it.quantityMilli))}});val attach=sale.shopCustomerId;if(attach!=null)payload.put("shopCustomerId",attach);db.withTransaction{val existing=db.dao().saleByMutation(mutation);if(existing!=null&&existing.id!=localSale){db.dao().deleteSaleItems(existing.id);db.dao().deleteSale(existing.id)};db.dao().putSale(SaleEntity(localSale,shopId,sale.subtotalPaise,sale.lines.size,"PENDING",mutation,created,shopCustomerId=attach,paymentType=if(credit)"CREDIT" else "PAID",creditAmountPaise=if(credit)total else 0,paymentMethod=sale.method.name,discountPaise=sale.discountPaise,subtotalPaise=sale.subtotalPaise,customerName=sale.customerName));db.dao().putSaleItems(sale.lines.values.map{SaleItemEntity(UUID.randomUUID().toString(),localSale,it.shopProductId,it.name,it.unit,it.unitPricePaise,it.quantityMilli,it.lineTotalPaise,it.costPricePaise)});if(credit&&attach!=null){val row=db.dao().shopCustomer(attach);if(row!=null){db.dao().putCredit(CreditTransactionEntity("local-credit-$mutation",shopId,row.id,"CREDIT_SALE",total,row.currentBalancePaise+total,"SALE",localSale,null,mutation,"PENDING",created));db.dao().setCreditBalance(row.id,row.currentBalancePaise+total,"PENDING",row.version+1)}};for(line in sale.lines.values){val row=db.dao().shopProduct(line.shopProductId)?:continue;val after=row.stockQuantityMilli-line.quantityMilli;if(after>=row.reservedQuantityMilli){db.dao().adjustLocalStock(line.shopProductId,-line.quantityMilli);db.dao().putInventory(InventoryTransactionEntity("local-saleinv-$mutation-${line.shopProductId}",shopId,line.shopProductId,"SALE",-line.quantityMilli,after,"${mutation}:${line.shopProductId}",created))}};db.dao().enqueue(Outbox(mutation,"QUICK_SALE",payload.toString()))};scheduleSync();return localSale}
 suspend fun addToPurchaseList(shopId:String,row:ProductRow,quantityMilli:Long){require(quantityMilli>0);val mutation=UUID.randomUUID().toString();val localId="local-purchase-$mutation";val now=System.currentTimeMillis();val payload=JSONObject().put("mutationId",mutation).put("shopId",shopId).put("shopProductId",row.shopProduct.id).put("quantityMilli",quantityMilli).toString();db.withTransaction{db.dao().putPurchaseItem(PurchaseListEntity(localId,shopId,row.shopProduct.id,row.product.name,quantityMilli,false,1,"PENDING",now));db.dao().enqueue(Outbox(mutation,"ADD_PURCHASE_ITEM",payload))};scheduleSync()}
 fun purchaseList(shopId:String)=db.dao().purchaseList(shopId)
 fun sales(shopId:String)=db.dao().sales(shopId)
 suspend fun customerSales(shopId:String,customerId:String):List<SaleEntity> = kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO){val all=db.dao().sales(shopId).first();all.filter{it.shopCustomerId==customerId}.take(50)}
 fun inventory(shopId:String,shopProductId:String)=db.dao().inventory(shopId,shopProductId)
 fun scheduleSync(){val request=androidx.work.OneTimeWorkRequestBuilder<CatalogueSyncWorker>().setConstraints(androidx.work.Constraints.Builder().setRequiredNetworkType(androidx.work.NetworkType.CONNECTED).build()).build();androidx.work.WorkManager.getInstance(context).enqueueUniqueWork("catalogue-sync",androidx.work.ExistingWorkPolicy.KEEP,request)}
 suspend fun syncPending(){for(op in db.dao().pending()){try{val b=JSONObject(op.payload);val response=when(op.operation){"CREATE_PRODUCT"->api.call("/v1/shops/${b.optString("shopId").ifBlank{findShopForLocalMutation(op.mutationId)}}/products","POST",b,true);"UPDATE_PRODUCT"->api.call("/v1/shops/${b.getString("shopId")}/products/${b.getString("shopProductId")}","PUT",b,true);"ARCHIVE_PRODUCT"->api.call("/v1/shops/${b.getString("shopId")}/products/${b.getString("shopProductId")}","DELETE",b,true);"UPLOAD_PRODUCT_IMAGE"->{val file=java.io.File(b.getString("filePath"));api.upload("/v1/shops/${b.getString("shopId")}/products/${b.getString("shopProductId")}/image",file.readBytes(),b.getString("mimeType"),op.mutationId)};"REMOVE_PRODUCT_IMAGE"->api.call("/v1/shops/${b.getString("shopId")}/products/${b.getString("shopProductId")}/image","DELETE",b,true);"STOCK_IN"->api.call("/v1/shops/${b.getString("shopId")}/products/${b.getString("shopProductId")}/stock-in","POST",b,true);"STOCK_OUT"->api.call("/v1/shops/${b.getString("shopId")}/products/${b.getString("shopProductId")}/stock-out","POST",b,true);"QUICK_SALE"->api.call("/v1/shops/${b.getString("shopId")}/sales","POST",b,true);"ADD_PURCHASE_ITEM"->api.call("/v1/shops/${b.getString("shopId")}/purchase-list","POST",b,true);"CUSTOMER_CREATE"->api.call("/v1/shops/${b.getString("shopId")}/customers","POST",b,true);"CUSTOMER_UPDATE"->api.call("/v1/shops/${b.getString("shopId")}/customers/${b.getString("shopCustomerId")}","PUT",b,true);"CUSTOMER_ARCHIVE"->api.call("/v1/shops/${b.getString("shopId")}/customers/${b.getString("shopCustomerId")}","DELETE",b,true);"CREDIT"->api.call("/v1/shops/${b.getString("shopId")}/customers/${b.getString("shopCustomerId")}/${creditEndpoint(b.getString("type"))}","POST",b,true);else->{db.dao().fail(op.mutationId,"Unsupported operation");continue}};if(op.operation=="ADD_PURCHASE_ITEM"){val sp=db.dao().shopProduct(response.getString("shopProductId"))!!;db.dao().deletePurchaseItem("local-purchase-${op.mutationId}");db.dao().putPurchaseItem(PurchaseListEntity(response.getString("id"),response.getString("shopId"),sp.id,db.dao().product(sp.productId)?.name?:"Product",response.getLong("quantityMilli"),response.getBoolean("isPurchased"),response.getLong("version"),"SYNCED",System.currentTimeMillis()));db.dao().ack(op.mutationId)}else if(op.operation=="STOCK_IN"||op.operation=="STOCK_OUT"){db.dao().setCanonicalStock(response.getString("shopProductId"),response.getLong("stockQuantityMilli"));db.dao().ack(op.mutationId) }else if(op.operation=="QUICK_SALE"){val localSaleId="local-sale-${op.mutationId}";val serverSaleId=response.getString("saleId");db.withTransaction{db.dao().remapSaleItems(localSaleId,serverSaleId);db.dao().completeSale(op.mutationId,serverSaleId)};val saleId=db.dao().saleByMutation(op.mutationId)?.id;for(line in saleItemsOf(saleId))db.dao().deleteInventory("local-saleinv-${op.mutationId}-${line.shopProductId}");if(response.optString("paymentType")=="CREDIT"){db.dao().deleteCredit("local-credit-${op.mutationId}");runCatching{refreshCustomers(b.getString("shopId"))}};db.dao().ack(op.mutationId);refreshProducts(b.getString("shopId"))}else if(op.operation=="UPLOAD_PRODUCT_IMAGE"||op.operation=="REMOVE_PRODUCT_IMAGE"){db.dao().setProductImage(response.getString("shopProductId"),response.optString("imageKey").takeIf{it.isNotBlank()&&it!="null"},"SYNCED",response.getLong("version"));if(op.operation=="UPLOAD_PRODUCT_IMAGE")java.io.File(b.getString("filePath")).delete();db.dao().ack(op.mutationId)}else if(op.operation=="CUSTOMER_CREATE"){db.withTransaction{val scid=response.getString("shopCustomerId");val cid=response.getString("customerId");db.dao().replacePendingId("local-shopcustomer-${op.mutationId}",scid);db.dao().replacePendingId("local-customer-${op.mutationId}",cid);db.dao().remapSaleCustomer("local-shopcustomer-${op.mutationId}",scid);db.dao().deleteShopCustomer("local-shopcustomer-${op.mutationId}");db.dao().deleteCustomer("local-customer-${op.mutationId}");mergeCustomerCamel(response)};db.dao().ack(op.mutationId)}else if(op.operation=="CUSTOMER_UPDATE"){db.withTransaction{mergeCustomerCamel(response)};db.dao().ack(op.mutationId)}else if(op.operation=="CUSTOMER_ARCHIVE"){db.dao().ack(op.mutationId)}else if(op.operation=="CREDIT"){db.withTransaction{db.dao().deleteCredit("local-credit-${op.mutationId}");val rf=response.opt("referenceType");val rd=response.opt("referenceId");val rn=response.opt("note");db.dao().putCredit(CreditTransactionEntity(response.getString("transactionId"),response.getString("shopId"),response.getString("shopCustomerId"),response.getString("type"),response.getLong("amountPaise"),response.getLong("balanceAfterPaise"),if(rf==null||rf==JSONObject.NULL)null else rf.toString(),if(rd==null||rd==JSONObject.NULL)null else rd.toString(),if(rn==null||rn==JSONObject.NULL)null else rn.toString(),op.mutationId,"SYNCED",response.optLong("createdAt",System.currentTimeMillis())));db.dao().setCreditBalanceOnly(response.getString("shopCustomerId"),response.getLong("balanceAfterPaise"),"SYNCED")};db.dao().ack(op.mutationId)}else if(op.operation!="ARCHIVE_PRODUCT")db.withTransaction{mergeProductResponse(response);if(op.operation=="CREATE_PRODUCT"){db.dao().replacePendingProductId("local-${op.mutationId}",response.getString("shopProductId"));db.dao().deleteInventory("local-tx-${op.mutationId}");db.dao().deleteShopProduct("local-${op.mutationId}");db.dao().deleteProduct("local-global-${op.mutationId}");val tx=response.optString("inventoryTransactionId");if(tx.isNotBlank())db.dao().putInventory(InventoryTransactionEntity(tx,response.getString("shopId"),response.getString("shopProductId"),"OPENING_STOCK",response.getLong("stockQuantityMilli"),response.getLong("stockQuantityMilli"),op.mutationId,System.currentTimeMillis()))};db.dao().ack(op.mutationId)}else db.dao().ack(op.mutationId)}catch(e:Exception){if(e is ApiException&&e.status in listOf(400,403,404,409)){val b=JSONObject(op.payload); if(op.operation=="STOCK_IN"||op.operation=="STOCK_OUT"){val q=b.getLong("quantityMilli");db.dao().adjustLocalStock(b.getString("shopProductId"),if(op.operation=="STOCK_IN")-q else q);db.dao().deleteInventory("local-${op.mutationId}")};if(op.operation=="QUICK_SALE"){val saleId=db.dao().saleByMutation(op.mutationId)?.id;db.dao().rejectSale(op.mutationId);db.dao().rejectCredit(op.mutationId);for(line in saleItemsOf(saleId))db.dao().adjustLocalStock(line.shopProductId,line.quantityMilli);for(line in saleItemsOf(saleId))db.dao().deleteInventory("local-saleinv-${op.mutationId}-${line.shopProductId}");runCatching{refreshCustomers(b.getString("shopId"))}};if(op.operation=="CREDIT"){db.dao().rejectCredit(op.mutationId);runCatching{refreshCustomers(b.getString("shopId"))}};if(op.operation=="CUSTOMER_CREATE"){db.dao().deleteShopCustomer("local-shopcustomer-${op.mutationId}");db.dao().deleteCustomer("local-customer-${op.mutationId}")};if(op.operation=="CUSTOMER_UPDATE"||op.operation=="CUSTOMER_ARCHIVE")runCatching{refreshCustomers(b.getString("shopId"))};db.dao().failPermanent(op.mutationId,e.message?:"Rejected by server")}else db.dao().fail(op.mutationId,e.message?:"Sync failed")}};if(db.dao().pending().isNotEmpty())throw IOException("Changes are saved offline and will retry")}
 private suspend fun findShopForLocalMutation(mutation:String):String {val p=db.dao().pending().first{it.mutationId==mutation}.payload;return JSONObject(p).optString("shopId").ifBlank{throw IllegalStateException("Missing shop")}}
 private suspend fun mergeProductResponse(x:JSONObject){val normalized=JSONObject().put("shop_product_id",x.getString("shopProductId")).put("shop_id",x.getString("shopId")).put("product_id",x.getString("productId")).put("name",x.getString("name")).put("brand",x.opt("brand")).put("barcode",x.opt("barcode")).put("unit",x.getString("unit")).put("description",x.opt("description")).put("selling_price_paise",x.getLong("sellingPricePaise")).put("stock_quantity_milli",x.getLong("stockQuantityMilli")).put("reserved_quantity_milli",x.getLong("reservedQuantityMilli")).put("minimum_stock_milli",x.getLong("minimumStockMilli")).put("is_available",if(x.getBoolean("isAvailable"))1 else 0).put("is_archived",if(x.getBoolean("isArchived"))1 else 0).put("version",x.getLong("version")).put("updated_at",System.currentTimeMillis());mergeProduct(normalized,"SYNCED")}
 private suspend fun mergeProduct(x:JSONObject,state:String){val pid=x.getString("product_id");val sid=x.getString("shop_product_id");val updated=x.optLong("updated_at",System.currentTimeMillis());db.dao().putProduct(ProductEntity(pid,x.optString("barcode").takeIf{it.isNotBlank() && it!="null"},x.getString("name"),x.optString("brand").takeIf{it.isNotBlank() && it!="null"},x.getString("unit"),x.optString("description").takeIf{it.isNotBlank() && it!="null"},updated));val existing=db.dao().shopProduct(sid);db.dao().putShopProduct(ShopProductEntity(sid,x.getString("shop_id"),pid,x.getLong("selling_price_paise"),x.getLong("stock_quantity_milli"),x.getLong("reserved_quantity_milli"),x.getLong("minimum_stock_milli"),x.optInt("is_available")==1,x.optInt("is_archived")==1,x.optString("image_key").takeIf{it.isNotBlank() && it!="null"},x.getLong("version"),state,updated,costPricePaise=existing?.costPricePaise?:0))}
 suspend fun logout(){runCatching{api.call("/v1/auth/logout","POST",authenticated=true)};sessions.clear();clearLocalAccountData()}
 /** Logout par poora account-scoped data udda do — agla login bilkul fresh shuru kare, kisi purane
  *  account ka shop/product/customer/sale leak na ho (auth bug ka doosra half). */
 suspend fun clearLocalAccountData(){val dao=db.dao();db.withTransaction{dao.deleteSaleItemsNotInShops(emptyList());dao.deleteSalesNotInShops(emptyList());dao.deleteInventoryNotInShops(emptyList());dao.deleteCreditNotInShops(emptyList());dao.deletePurchaseNotInShops(emptyList());dao.deleteShopCustomersNotInShops(emptyList());dao.deleteOrphanCustomers();dao.deleteShopProductsNotInShops(emptyList());dao.deleteOrphanProducts();dao.deleteShopsNotIn(emptyList());dao.putProfile(LocalProfile("","","",false,false,false))}}
 fun customers(shopId:String):Flow<List<ShopCustomerEntity>> = db.dao().customers(shopId)
 fun creditStatement(shopId:String,customerId:String):Flow<List<CreditTransactionEntity>> = db.dao().creditStatement(shopId,customerId)
 fun creditEndpoint(type:String)=when(type){"CREDIT_SALE"->"credit";"PAYMENT"->"payment";else->"adjustment"}
 private fun normalizeMobile(mobile:String?):String?{val m=mobile?.trim()?.takeIf{it.isNotBlank()}?:return null;return if(m.startsWith("+"))m else "+91"+m.filter(Char::isDigit).takeLast(10)}
 suspend fun refreshCustomers(shopId:String){val items=api.call("/v1/shops/$shopId/customers",authenticated=true).getJSONArray("items");db.withTransaction{for(i in 0 until items.length())mergeCustomer(items.getJSONObject(i))}}
 private suspend fun saleItemsOf(saleId:String?):List<SaleItemEntity> = if(saleId==null)emptyList<SaleItemEntity>() else db.dao().saleItems(saleId)
 /** POS ke chhote customer form ke liye — sirf naam+mobile; udhaari turant isi customer par hota hai. */
 suspend fun quickAddCustomer(shopId:String,name:String,mobile:String?):ShopCustomerEntity{val normalized=normalizeMobile(mobile);val mutation=UUID.randomUUID().toString();val localCustomer="local-customer-$mutation";val localShopCustomer="local-shopcustomer-$mutation";val now=System.currentTimeMillis();val payload=JSONObject().put("mutationId",mutation).put("shopId",shopId).put("name",name.trim()).put("mobile",normalized?:JSONObject.NULL).put("creditEnabled",false).put("creditLimitPaise",JSONObject.NULL).put("notes",JSONObject.NULL).toString();val entity=ShopCustomerEntity(localShopCustomer,shopId,localCustomer,name.trim(),normalized,null,false,null,0L,false,1L,"PENDING",now);db.withTransaction{db.dao().putCustomer(CustomerEntity(localCustomer,name.trim(),normalized,now));db.dao().putShopCustomer(entity);db.dao().enqueue(Outbox(mutation,"CUSTOMER_CREATE",payload))};scheduleSync();return entity}
 suspend fun createCustomer(shopId:String,name:String,mobile:String?,creditEnabled:Boolean,creditLimitPaise:Long?,notes:String?){val mutation=UUID.randomUUID().toString();val localCustomer="local-customer-$mutation";val localShopCustomer="local-shopcustomer-$mutation";val normalized=normalizeMobile(mobile);val cleanNotes=notes?.trim()?.takeIf{it.isNotBlank()};val now=System.currentTimeMillis();val payload=JSONObject().put("mutationId",mutation).put("shopId",shopId).put("name",name.trim()).put("mobile",normalized?:JSONObject.NULL).put("creditEnabled",creditEnabled).put("creditLimitPaise",creditLimitPaise?:JSONObject.NULL).put("notes",cleanNotes?:JSONObject.NULL).toString();db.withTransaction{db.dao().putCustomer(CustomerEntity(localCustomer,name.trim(),normalized,now));db.dao().putShopCustomer(ShopCustomerEntity(localShopCustomer,shopId,localCustomer,name.trim(),normalized,cleanNotes,creditEnabled,creditLimitPaise,0L,false,1L,"PENDING",now));db.dao().enqueue(Outbox(mutation,"CUSTOMER_CREATE",payload))};scheduleSync()}
 suspend fun updateCustomer(shopId:String,row:ShopCustomerEntity,name:String,mobile:String?,creditEnabled:Boolean,creditLimitPaise:Long?,notes:String?){val mutation=UUID.randomUUID().toString();val normalized=normalizeMobile(mobile);val cleanNotes=notes?.trim()?.takeIf{it.isNotBlank()};val payload=JSONObject().put("mutationId",mutation).put("shopId",shopId).put("version",row.version).put("name",name.trim()).put("mobile",normalized?:JSONObject.NULL).put("creditEnabled",creditEnabled).put("creditLimitPaise",creditLimitPaise?:JSONObject.NULL).put("notes",cleanNotes?:JSONObject.NULL).toString();db.withTransaction{db.dao().putCustomer(CustomerEntity(row.customerId,name.trim(),normalized,System.currentTimeMillis()));db.dao().putShopCustomer(row.copy(displayName=name.trim(),normalizedPhone=normalized,notes=cleanNotes,creditEnabled=creditEnabled,creditLimitPaise=creditLimitPaise,syncState="PENDING",updatedAt=System.currentTimeMillis()));db.dao().enqueue(Outbox(mutation,"CUSTOMER_UPDATE",payload))};scheduleSync()}
 suspend fun archiveCustomer(shopId:String,shopCustomerId:String){val mutation=UUID.randomUUID().toString();val payload=JSONObject().put("mutationId",mutation).put("shopId",shopId).put("shopCustomerId",shopCustomerId).toString();db.withTransaction{db.dao().archiveCustomer(shopCustomerId);db.dao().enqueue(Outbox(mutation,"CUSTOMER_ARCHIVE",payload))};scheduleSync()}
 suspend fun credit(shopId:String,shopCustomerId:String,type:String,amountPaise:Long,note:String?){require(amountPaise>0){"Amount must be greater than zero"};val row=db.dao().shopCustomer(shopCustomerId)?:throw IOException("Customer not found");val positive=type=="CREDIT_SALE"||type=="ADJUSTMENT_CREDIT";val delta=if(positive)amountPaise else -amountPaise;require(row.currentBalancePaise+delta>=0){"Payment exceeds current balance"};val mutation=UUID.randomUUID().toString();val cleanNote=note?.trim()?.takeIf{it.isNotBlank()};val now=System.currentTimeMillis();val balanceAfter=row.currentBalancePaise+delta;val payload=JSONObject().put("mutationId",mutation).put("shopId",shopId).put("shopCustomerId",shopCustomerId).put("amountPaise",amountPaise).put("type",type).put("note",cleanNote?:JSONObject.NULL).toString();db.withTransaction{db.dao().putCredit(CreditTransactionEntity("local-credit-$mutation",shopId,shopCustomerId,type,amountPaise,balanceAfter,null,null,cleanNote,mutation,"PENDING",now));db.dao().setCreditBalance(shopCustomerId,balanceAfter,"PENDING",row.version+1);db.dao().enqueue(Outbox(mutation,"CREDIT",payload))};scheduleSync()}
 private suspend fun mergeCustomer(x:JSONObject){val scid=x.getString("shop_customer_id");val cid=x.getString("customer_id");val name=x.getString("display_name");val phone=x.optString("normalized_phone").takeIf{it.isNotBlank()&&it!="null"};val rawLimit=x.opt("credit_limit_paise");val limit=if(rawLimit==null||rawLimit==JSONObject.NULL)null else (rawLimit as Number).toLong();db.dao().putCustomer(CustomerEntity(cid,name,phone,System.currentTimeMillis()));db.dao().putShopCustomer(ShopCustomerEntity(scid,x.getString("shop_id"),cid,name,phone,x.optString("notes").takeIf{it.isNotBlank()&&it!="null"},x.optInt("credit_enabled")==1,limit,x.optLong("current_balance_paise"),x.optInt("is_archived")==1,x.optLong("version",1),"SYNCED",x.optLong("updated_at",System.currentTimeMillis())))}
 private suspend fun mergeCustomerCamel(x:JSONObject){val scid=x.getString("shopCustomerId");val cid=x.getString("customerId");val name=x.getString("displayName");val phone=x.optString("normalizedPhone").takeIf{it.isNotBlank()&&it!="null"};val rawLimit=x.opt("creditLimitPaise");val limit=if(rawLimit==null||rawLimit==JSONObject.NULL)null else (rawLimit as Number).toLong();db.dao().putCustomer(CustomerEntity(cid,name,phone,System.currentTimeMillis()));db.dao().putShopCustomer(ShopCustomerEntity(scid,x.getString("shopId"),cid,name,phone,x.optString("notes").takeIf{it.isNotBlank()&&it!="null"},x.optBoolean("creditEnabled"),limit,x.optLong("currentBalancePaise"),x.optBoolean("isArchived"),x.optLong("version",1),"SYNCED",System.currentTimeMillis()))}
 private fun encode(v:String)=java.net.URLEncoder.encode(v,"UTF-8")
 private fun marketShop(x:JSONObject)=MarketShop(x.getString("id"),x.getString("name"),x.optString("category"),x.optString("locality"),x.optString("city"),x.optString("public_slug").takeIf{it.isNotBlank()&&it!="null"},if(x.isNull("distance_m"))null else x.optLong("distance_m"),x.optInt("delivery_enabled")==1,x.optLong("minimum_order_paise"),x.optLong("delivery_fee_paise"))
 private fun orderSummary(o:JSONObject)=OrderSummary(o.getString("id"),o.getString("shop_id"),o.optString("shop_name"),o.getString("status"),o.getString("fulfillment_type"),o.getLong("total_paise"),o.getLong("created_at"))
 suspend fun nearbyShops(latitude:Double?,longitude:Double?,q:String):List<MarketShop>{var path=if(latitude!=null&&longitude!=null)"/v1/market/shops?latitude=$latitude&longitude=$longitude&radiusM=10000" else "/v1/market/shops";if(q.isNotBlank())path+=(if(path.contains('?'))"&" else "?")+"q=${encode(q)}";val items=api.call(path,authenticated=true).getJSONArray("items");return (0 until items.length()).map{marketShop(items.getJSONObject(it))}}
 suspend fun shopPage(slug:String):Pair<MarketShop,List<MarketProduct>>{val x=api.call("/v1/market/shops/${encode(slug)}",authenticated=true);val items=x.getJSONArray("items");return marketShop(x.getJSONObject("shop")) to (0 until items.length()).map{val o=items.getJSONObject(it);MarketProduct(o.getString("shop_product_id"),o.getString("name"),o.optString("brand").takeIf{b->b.isNotBlank()&&b!="null"},o.getString("unit"),o.getLong("selling_price_paise"),o.getLong("stock_quantity_milli"))}}
 suspend fun addresses():List<OrderAddress>{val items=api.call("/v1/addresses",authenticated=true).getJSONArray("items");return (0 until items.length()).map{val o=items.getJSONObject(it);OrderAddress(o.getString("id"),o.optString("recipient_name"),o.optString("address_line"),o.optString("locality"),o.optString("city"),o.optString("pincode"),o.optString("mobile_e164").takeIf{m->m.isNotBlank()&&m!="null"})}}
 suspend fun createAddress(recipient:String,mobile:String,addressLine:String,locality:String,city:String,pincode:String):OrderAddress{val digits=mobile.filter{it.isDigit()};val normalized=when{recipient.isBlank()->null;mobile.isBlank()->null;mobile.startsWith("+")->mobile else->"+91"+digits.takeLast(10)};val x=api.call("/v1/addresses","POST",JSONObject().put("mutationId",UUID.randomUUID().toString()).put("recipientName",recipient).put("mobile",normalized?:JSONObject.NULL).put("addressLine",addressLine).put("locality",locality).put("city",city).put("pincode",pincode),true);return OrderAddress(x.getString("id"),x.getString("recipientName"),x.getString("addressLine"),x.getString("locality"),x.getString("city"),x.getString("pincode"),x.optString("mobile").takeIf{m->m.isNotBlank()&&m!="null"})}
 suspend fun placeOrder(shopId:String,cart:Cart,fulfillmentType:String,addressId:String?,note:String):JSONObject{val b=JSONObject().put("mutationId",UUID.randomUUID().toString()).put("shopId",shopId).put("fulfillmentType",fulfillmentType).put("items",org.json.JSONArray().apply{cart.lines.forEach{put(JSONObject().put("shopProductId",it.shopProductId).put("quantityMilli",it.quantityMilli))}});if(addressId!=null)b.put("addressId",addressId);if(note.isNotBlank())b.put("note",note);return api.call("/v1/orders","POST",b,true)}
 suspend fun salesSince(shopId:String,since:Long):List<SaleEntity> = db.dao().salesSince(shopId,since)
 /** Profit sirf tab dikhe jab purchase price record ho rakha ho — warna overestimate hota. */
 suspend fun profitEstimate(shopId:String,since:Long):Long?{val cost=try{db.dao().costSince(shopId,since)}catch(_:Throwable){return null};return if(cost>0)try{db.dao().profitSince(shopId,since)}catch(_:Throwable){null} else null}
 suspend fun duesPair(shopId:String):Pair<Long,Int> = runCatching{db.dao().totalDue(shopId) to db.dao().dueCount(shopId)}.getOrDefault(0L to 0)
 /** Receipt banata hai — local PENDING aur synced COMPLETED dono chalega. */
 suspend fun receiptData(shopId:String,saleId:String):ReceiptData?{val sale=db.dao().sales(shopId).first().firstOrNull{it.id==saleId}?:return null;val items=db.dao().saleItems(saleId);val shop=db.dao().shops().first().firstOrNull{it.id==shopId};val credit=sale.paymentType=="CREDIT";val method=try{PaymentMethod.valueOf(sale.paymentMethod)}catch(_:Throwable){PaymentMethod.CASH};val subtotal=if(sale.subtotalPaise>0)sale.subtotalPaise else sale.totalPaise+sale.discountPaise;val shopLine=listOfNotNull(shop?.addressLine?.takeIf{it.isNotBlank()},shop?.locality?.takeIf{it.isNotBlank()},shop?.city?.takeIf{it.isNotBlank()},shop?.phone?.takeIf{it.isNotBlank()}).joinToString(" • ").ifBlank{null};return ReceiptData(sale.id,shop?.name?:"LocalDukaan",shopLine,sale.createdAt,items.map{QuickSaleLine(it.shopProductId,it.productName,it.unit,it.unitPricePaise,it.quantityMilli,it.costPricePaise)},subtotal,sale.discountPaise,sale.totalPaise,method.label,sale.customerName?:(if(credit)"Customer" else "Walk-in Customer"),if(credit)0L else sale.totalPaise,if(credit)sale.totalPaise else 0L,sale.status=="PENDING")}
 fun shareReceiptText(text:String){val i=android.content.Intent(android.content.Intent.ACTION_SEND).apply{type="text/plain";putExtra(android.content.Intent.EXTRA_TEXT,text)};context.startActivity(android.content.Intent.createChooser(i,null).addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK))}
 suspend fun myCredit():Pair<List<MyCreditShop>,List<MyCreditEntry>>{val x=api.call("/v1/my/credit",authenticated=true);val items=x.getJSONArray("items");val recent=x.getJSONArray("recent");return (0 until items.length()).map{val o=items.getJSONObject(it);MyCreditShop(o.getString("shop_id"),o.getString("shop_name"),o.getLong("balance_paise"),if(o.isNull("credit_limit_paise"))null else o.getLong("credit_limit_paise"),o.getLong("updated_at"))} to (0 until recent.length()).map{val o=recent.getJSONObject(it);MyCreditEntry(o.getString("shop_name"),o.getString("type"),o.getLong("amount_paise"),o.getLong("balance_after_paise"),o.getLong("created_at"))}}
 suspend fun myOrders():List<OrderSummary>{val items=api.call("/v1/orders",authenticated=true).getJSONArray("items");return (0 until items.length()).map{orderSummary(items.getJSONObject(it))}}
 suspend fun shopOrders(shopId:String,status:String):List<OrderSummary>{val items=api.call("/v1/shops/$shopId/orders"+(if(status.isBlank())"" else "?status=$status"),authenticated=true).getJSONArray("items");return (0 until items.length()).map{orderSummary(items.getJSONObject(it))}}
 suspend fun orderDetail(orderId:String):OrderDetail{val x=api.call("/v1/orders/${encode(orderId)}",authenticated=true);val items=x.getJSONArray("items");val history=x.optJSONArray("history");return OrderDetail(x.getString("id"),x.getString("shop_id"),x.getString("status"),x.getString("fulfillment_type"),x.getLong("total_paise"),x.optLong("delivery_fee_paise"),(0 until items.length()).map{val o=items.getJSONObject(it);OrderLine(o.getString("shop_product_id"),o.getString("product_name_snapshot"),o.getString("unit_snapshot"),o.getLong("unit_price_paise"),o.getLong("quantity_milli"),o.getLong("line_total_paise"))},history?.let{h->(0 until h.length()).map{h.getJSONObject(it).getString("status")}}?:emptyList())}
 suspend fun cancelOrder(orderId:String)=api.call("/v1/orders/${encode(orderId)}/cancel","POST",JSONObject().put("mutationId",UUID.randomUUID().toString()),true)
 suspend fun advanceOrder(shopId:String,orderId:String,status:String)=api.call("/v1/shops/$shopId/orders/${encode(orderId)}/status","POST",JSONObject().put("mutationId",UUID.randomUUID().toString()).put("status",status),true)
 fun loggedIn()=sessions.loggedIn()
}
